class Solution {
  private static void zFunction(int[] a, int off, int[] z) {
    int len = a.length - off;
    z[0] = len;
    for (int i = 1, l = 0, r = 0; i < len; i++) {
      int k = i < r ? Math.min(r - i, z[i - l]) : 0;
      while (i + k < len && a[off + k] == a[off + i + k]) k++;
      z[i] = k;
      if (i + k > r) {
        l = i;
        r = i + k;
      }
    }
  }

  public int beautifulSplits(int[] nums) {
    int n = nums.length;
    int[] z0 = new int[n], zi = new int[n];
    zFunction(nums, 0, z0);
    int ans = 0;
    for (int i = 1; i <= n - 2; i++) {
      zFunction(nums, i, zi);
      boolean prefixOk = z0[i] >= i;
      for (int j = i + 1; j <= n - 1; j++) {
        int len = j - i;
        if ((prefixOk && len >= i) || (j + len <= n && zi[len] >= len)) ans++;
      }
    }
    return ans;
  }
}
